import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];

  const colors = {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // Prism geometry
  const prismGeometry = createPrismGeometry();
  const prismMaterial = new THREE.MeshPhysicalMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    color: new THREE.Color(colors.paper),
    attenuationColor: new THREE.Color(colors.paper),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480]
  });

  const prism = new THREE.Mesh(prismGeometry, prismMaterial);
  prism.rotation.z = THREE.MathUtils.degToRad(12);
  prism.rotation.y = THREE.MathUtils.degToRad(20);
  group.add(prism);

  // Emissive octahedron core
  const coreGeometry = new THREE.OctahedronGeometry(0.35, 2);
  const coreMaterial = new THREE.MeshBasicMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 2.2
  });
  const core = new THREE.Mesh(coreGeometry, coreMaterial);
  group.add(core);

  // Back rim light
  const rimLight = new THREE.DirectionalLight(0x9fb0c4, 1.5);
  rimLight.position.set(-1.5, 0.5, -1.8);
  group.add(rimLight);

  // Caustic streak with gradient texture
  const causticTexture = createGradientTexture([
    { stop: 0.2, hex: '#ff2a38' },
    { stop: 0.5, hex: '#e8ecf2' },
    { stop: 0.8, hex: '#9fb0c4' }
  ]);

  const causticGeometry = new THREE.PlaneGeometry(2.4, 0.5);
  const causticMaterial = new THREE.MeshBasicMaterial({
    map: causticTexture,
    transparent: true,
    opacity: 0.35,
    side: THREE.DoubleSide
  });
  const caustic = new THREE.Mesh(causticGeometry, causticMaterial);
  caustic.position.y = -1.1;
  caustic.rotation.x = -Math.PI / 2;
  group.add(caustic);

  // Text via fontAtlas
  if (ctx.fontAtlas) {
    const headline = ctx.fontAtlas.createText('Light, machined.', {
      fontSize: 68,
      fontWeight: 600,
      family: 'Lora',
      color: colors.paper
    });
    if (headline) {
      headline.position.set(0, -1.75, 0.2);
      group.add(headline);
    }

    const caption = ctx.fontAtlas.createText('SAPPHIRE OVER DIAL / ZERO DISTORTION', {
      fontSize: 18,
      fontWeight: 400,
      family: 'JetBrains Mono',
      color: colors.paper,
      letterSpacing: 0.08
    });
    if (caption) {
      caption.position.set(0, -2.25, 0.2);
      group.add(caption);
    }
  }

  // Apply cinematic primitive: depth-rotate
  if (ctx.primitives?.['depth-rotate']) {
    ctx.primitives['depth-rotate'](group, { maxDeg: 10 });
  }

  // Event handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    prismGeometry.dispose();
    prismMaterial.dispose();
    coreGeometry.dispose();
    coreMaterial.dispose();
    causticGeometry.dispose();
    causticMaterial.dispose();
    causticTexture.dispose();
    timelines.forEach(t => t.kill());
  };

  return group;

  function createPrismGeometry() {
    const geometry = new THREE.BufferGeometry();
    const side = 1.2;
    const length = 1.8;
    const h = (side * Math.sqrt(3)) / 2;
    const halfL = length / 2;

    const vertices = new Float32Array([
      0, (h / 3), -halfL,
      -(side / 2), -(h / 3), -halfL,
      side / 2, -(h / 3), -halfL,
      0, (h / 3), halfL,
      -(side / 2), -(h / 3), halfL,
      side / 2, -(h / 3), halfL
    ]);

    const indices = new Uint32Array([
      0, 1, 2,
      3, 5, 4,
      0, 1, 4,
      0, 4, 3,
      0, 2, 5,
      0, 5, 3,
      1, 2, 5,
      1, 5, 4
    ]);

    geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
    geometry.setIndex(new THREE.BufferAttribute(indices, 1));
    geometry.computeVertexNormals();

    return geometry;
  }

  function createGradientTexture(stops) {
    const width = 512;
    const height = 128;
    const data = new Uint8Array(width * height * 4);

    for (let i = 0; i < width; i++) {
      const t = i / width;
      const color = interpolateGradient(t, stops);

      for (let j = 0; j < height; j++) {
        const idx = (j * width + i) * 4;
        data[idx] = color.r;
        data[idx + 1] = color.g;
        data[idx + 2] = color.b;
        data[idx + 3] = 255;
      }
    }

    const texture = new THREE.DataTexture(data, width, height, THREE.RGBAFormat);
    texture.needsUpdate = true;
    return texture;
  }

  function interpolateGradient(t, stops) {
    for (let i = 0; i < stops.length - 1; i++) {
      if (t >= stops[i].stop && t <= stops[i + 1].stop) {
        const range = stops[i + 1].stop - stops[i].stop;
        const local = range > 0 ? (t - stops[i].stop) / range : 0;
        const c1 = new THREE.Color(stops[i].hex);
        const c2 = new THREE.Color(stops[i + 1].hex);
        return {
          r: Math.round(c1.r * 255 * (1 - local) + c2.r * 255 * local),
          g: Math.round(c1.g * 255 * (1 - local) + c2.g * 255 * local),
          b: Math.round(c1.b * 255 * (1 - local) + c2.b * 255 * local)
        };
      }
    }
    const lastStop = stops[stops.length - 1];
    const c = new THREE.Color(lastStop.hex);
    return {
      r: Math.round(c.r * 255),
      g: Math.round(c.g * 255),
      b: Math.round(c.b * 255)
    };
  }
}
